% Generated by simulink/build_simulink.py from handwritten.sim.json.
% Edit the .sim.json (values, gate timing) and rebuild rather than editing this file.
model = 'handwritten_sim';
here = fileparts(mfilename('fullpath'));
if bdIsLoaded(model), close_system(model, 0); end
new_system(model); load_system('fl_lib'); load_system('ee_lib'); load_system('nesl_utility');
set_param(model, 'Solver', 'ode23t', 'StopTime', '0.001', 'MaxStep', '1e-06', 'ReturnWorkspaceOutputs', 'on');

put(model, 'fl_lib/Electrical/Electrical Sources/DC Voltage Source', 'B1', 500, 530, 'right', 50, 40);
set_param([model '/' 'B1'], 'v0', '5', 'v0_unit', 'V');
put(model, 'fl_lib/Electrical/Electrical Elements/Resistor', 'R1', 790, 380, 'right', 50, 40);
set_param([model '/' 'R1'], 'R', '5', 'R_unit', 'Ohm');
put(model, 'fl_lib/Electrical/Electrical Elements/Capacitor', 'C1', 630, 530, 'down', 50, 40);
set_param([model '/' 'C1'], 'c', '3e-06', 'c_unit', 'F');
put(model, 'fl_lib/Electrical/Electrical Elements/Resistor', 'R2', 1060, 530, 'down', 50, 40);
set_param([model '/' 'R2'], 'R', '2', 'R_unit', 'Ohm');
put(model, 'fl_lib/Electrical/Electrical Elements/Electrical Reference', 'Ground', 630, 619, 'down', 40, 40);
put(model, 'nesl_utility/Solver Configuration', 'Solver', 540, 609, 'right', 50, 40);

put(model, 'fl_lib/Electrical/Electrical Sensors/Voltage Sensor', 'V_B1p', 1380, 380, 'right', 50, 40);
put(model, 'nesl_utility/PS-Simulink Converter', 'PS_B1p', 1480, 368, 'right', 50, 40);
add_block('simulink/Sinks/To Workspace', [model '/log_B1p'], 'Position', [1540 333 1620 353]);
set_param([model '/log_B1p'], 'VariableName', 'v_B1p', 'SaveFormat', 'Array');
wire(model, 'V_B1p', 'RConn1', 'PS_B1p', 'LConn1');
wire(model, 'PS_B1p', 'Outport1', 'log_B1p', 'Inport1');
put(model, 'nesl_utility/Connection Label', 'Lm_B1p', 1310, 382, 'left', 30, 16, 'off');
set_param([model '/Lm_B1p'], 'Label', 'B1p');
wire(model, 'Lm_B1p', 'LConn1', 'V_B1p', 'LConn1');
put(model, 'fl_lib/Electrical/Electrical Elements/Electrical Reference', 'Gnd_B1p', 1425, 425, 'down', 30, 30, 'off');
wire(model, 'V_B1p', 'RConn2', 'Gnd_B1p', 'LConn1');
put(model, 'nesl_utility/Connection Label', 'L_B1p', 471, 485, 'up', 30, 16, 'off');
set_param([model '/L_B1p'], 'Label', 'B1p');
put(model, 'fl_lib/Electrical/Electrical Sensors/Voltage Sensor', 'V_R1_right', 1380, 480, 'right', 50, 40);
put(model, 'nesl_utility/PS-Simulink Converter', 'PS_R1_right', 1480, 468, 'right', 50, 40);
add_block('simulink/Sinks/To Workspace', [model '/log_R1_right'], 'Position', [1540 433 1620 453]);
set_param([model '/log_R1_right'], 'VariableName', 'v_R1_right', 'SaveFormat', 'Array');
wire(model, 'V_R1_right', 'RConn1', 'PS_R1_right', 'LConn1');
wire(model, 'PS_R1_right', 'Outport1', 'log_R1_right', 'Inport1');
put(model, 'nesl_utility/Connection Label', 'Lm_R1_right', 1310, 482, 'left', 30, 16, 'off');
set_param([model '/Lm_R1_right'], 'Label', 'R1_right');
wire(model, 'Lm_R1_right', 'LConn1', 'V_R1_right', 'LConn1');
put(model, 'fl_lib/Electrical/Electrical Elements/Electrical Reference', 'Gnd_R1_right', 1425, 525, 'down', 30, 30, 'off');
wire(model, 'V_R1_right', 'RConn2', 'Gnd_R1_right', 'LConn1');
put(model, 'nesl_utility/Connection Label', 'L_R1_right', 819, 335, 'up', 30, 16, 'off');
set_param([model '/L_R1_right'], 'Label', 'R1_right');
add_block('simulink/Signal Routing/Mux', [model '/Mux'], 'Position', [1690 390 1695 470]);
set_param([model '/Mux'], 'Inputs', '2');
put(model, 'simulink/Sinks/Scope', 'Node voltages', 1770, 430, 'right', 40, 40);
wire(model, 'Mux', 'Outport1', 'Node voltages', 'Inport1');
wire(model, 'PS_B1p', 'Outport1', 'Mux', 'Inport1');
wire(model, 'PS_R1_right', 'Outport1', 'Mux', 'Inport2');

% net R2_right
wire(model, 'Solver', 'RConn1', 'B1', 'RConn1');
wire(model, 'Ground', 'LConn1', 'Solver', 'RConn1');
wire(model, 'C1', 'RConn1', 'Ground', 'LConn1');
wire(model, 'R2', 'RConn1', 'C1', 'RConn1');
% net B1+
wire(model, 'L_B1p', 'LConn1', 'B1', 'LConn1');
wire(model, 'C1', 'LConn1', 'L_B1p', 'LConn1');
wire(model, 'R1', 'LConn1', 'C1', 'LConn1');
% net R1_right
wire(model, 'L_R1_right', 'LConn1', 'R1', 'RConn1');
wire(model, 'R2', 'LConn1', 'R1', 'RConn1');

set_param(model, 'SimscapeLogType', 'all');  % only exists once Simscape blocks are in the model
save_system(model, fullfile(here, [model '.slx']));
result = struct('ok', true, 'error', '', 'nodes', struct('name', {}, 'final', {}, 'min', {}, 'max', {}), 'parts', struct('name', {}, 'v_final', {}, 'v_min', {}, 'v_max', {}, 'i_final', {}, 'i_min', {}, 'i_max', {}));
try
    out = sim(model);
    t = out.get('tout');
    window = t >= t(end) - 0.0002;  % last period / settled part
    nets = {'B1+', 'v_B1p', 'R1_right', 'v_R1_right'};
    for k = 1:2:numel(nets)
        v = out.get(nets{k + 1});
        result.nodes(end + 1) = struct('name', nets{k}, 'final', v(end), 'min', min(v(window)), 'max', max(v(window)));
    end
    lg = out.get('simlog');
    for name = {'B1', 'R1', 'C1', 'R2'}
        try
            node = lg.(matlab.lang.makeValidName(name{1}));
            vn = pick(node, {'v', 'vak'}); in = pick(node, {'i', 'iak'});
            tv = vn.series.time; vv = vn.series.values(vn.series.unit); iv = in.series.values(in.series.unit);
            w = tv >= t(end) - (t(end) - t(1)) / 5;
            result.parts(end + 1) = struct('name', name{1}, 'v_final', vv(end), 'v_min', min(vv(w)), 'v_max', max(vv(w)), 'i_final', iv(end), 'i_min', min(iv(w)), 'i_max', max(iv(w)));
        catch
        end
    end
catch err
    result.ok = false; result.error = err.message;
end
fid = fopen(fullfile(here, [model '.results.json']), 'w'); fprintf(fid, '%s', jsonencode(result)); fclose(fid);
save_system(model, fullfile(here, [model '.slx']));
close_system(model, 0);

function put(model, src, name, cx, cy, o, w, h, show)
    b = add_block(src, [model '/' name]);
    set_param(b, 'Orientation', o);
    if any(strcmp(o, {'up', 'down'})), [w, h] = deal(h, w); end
    set_param(b, 'Position', round([cx - w/2, cy - h/2, cx + w/2, cy + h/2]));
    if nargin > 8, set_param(b, 'ShowName', show); end
end

function wire(model, b1, p1, b2, p2)
    add_line(model, port(model, b1, p1), port(model, b2, p2), 'autorouting', 'smart');
end

function h = port(model, b, p)
    ph = get_param([model '/' b], 'PortHandles');
    kind = regexprep(p, '\d+$', ''); idx = str2double(regexprep(p, '^\D+', ''));
    h = ph.(kind)(idx);
end

function n = pick(node, names)
    for k = 1:numel(names)
        if any(strcmp(node.childIds, names{k})), n = node.(names{k}); return; end
    end
    error('no %s', strjoin(names, '/'));
end
